mapper.select:
select f.flow_id, f.biz_type, f.biz_id, f.user_id, u.user_name, f.action_type, f.from_status, f.to_status, f.action_detail, f.operator_id, f.operator_name, f.operate_time from emp_flow_log f left join sys_user u on f.user_id = u.user_id
and f.flow_id = #{flowId}
and f.biz_type = #{bizType}
and f.biz_id = #{bizId}
and f.user_id = #{userId}
and f.action_type = #{actionType}
and f.operator_name like concat('%', #{operatorName}, '%')
and u.user_name like concat('%', #{userName}, '%')
and f.operate_time >= #{params.beginTime}
and f.operate_time <= #{params.endTime}
order by f.operate_time desc, f.flow_id desc

select
DATE_FORMAT(f.operate_time, '%x-W%v')
DATE_FORMAT(f.operate_time, '%Y-%m-%d')
as statTime, count(1) as totalCount, sum(case when f.biz_type = 'PROFILE' then 1 else 0 end) as profileCount, sum(case when f.biz_type = 'APPLY' then 1 else 0 end) as applyCount, sum(case when f.biz_type = 'TRAINING' then 1 else 0 end) as trainingCount, sum(case when f.biz_type = 'CONSULT' then 1 else 0 end) as consultCount, sum(case when f.biz_type = 'POLICY' then 1 else 0 end) as policyCount from emp_flow_log f left join sys_user u on f.user_id = u.user_id
and f.biz_type = #{bizType}
and f.action_type = #{actionType}
and f.operator_name like concat('%', #{operatorName}, '%')
and u.user_name like concat('%', #{userName}, '%')
and f.operate_time >= #{params.beginTime}
and f.operate_time <= #{params.endTime}
group by statTime order by statTime asc
